#include <map>
#include <utility>

int main() {
    std::map<int, double> m;
    m.insert({10, 5.5});

    auto it = m.begin();

    // The type pointed to by 'it' is std::pair<const int, double>
    // it->first = 20; // ERROR: key is const

    // Modifying the value component is allowed
    it->second = 6.0; // OK

    // Insertion returns a pair of (iterator, bool)
    auto result = m.insert(std::make_pair(5, 2.2));
    bool success = result.second; // true
}
